<?php	/**	 * Created by PhpStorm.	 * User: MrHa	 * Date: 1/11/2015	 * Time: 11:41 PM	 */	$post_terms_data = get_the_terms( get_the_ID(), 'portfolio_cat' );	$data_cat = '';	foreach ( $post_terms_data as $val ) {		$data_cat .= $val->slug . ', ';	}	$data_cat = rtrim( $data_cat );	$data_cat = rtrim( $data_cat, ',' );	$post_format = get_post_meta( get_the_ID(), 'post_format', TRUE );	switch ( $post_format ) {		case "image":			$icon = 'fa-camera';			break;		case "video":			$icon = "fa-film";			break;		case "audio":			$icon = "fa-file-audio-o";			break;		case "quote":			$icon = "fa-quote-left";			break;		case "link":			$icon = "fa-link";			break;		case "gallery":			$icon = "fa-picture-o";			break;		default:			$icon = '';	}	echo '                            <article class="' . $data_cat . '">                              <a href="' . get_the_permalink() . '" class="permalink" onclick="return false;">                                ' . get_the_post_thumbnail( get_the_ID(), 'full' ) . '                                <div class="overlay">                                  <i class="fa ' . $icon . '"></i>                                  <h3>' . get_the_title() . '</h3>                                  <span>' . $data_cat . '</span>                                </div>                                <!-- End .overlay -->                              </a>                            </article> ';